def gen(rng):
    def fmt(ds, As):
        return str(len(ds)) + '\n' + '\n'.join('%d %d' % (d, a) for d, a in zip(ds, As))
    B = 10 ** 9
    tests = [fmt([1], [7]), fmt([3, 1, 1], [30, 20, 10]), fmt([2, 2, 1, 1], [7, 8, 9, 5]),
             fmt([1, 1, 1], [5, 5, 5]), fmt([3, 2, 1], [1, 2, 3]), fmt([1, 1], [B, 1])]
    for n in (2, 3, 4, 5, 8, 12, 20, 30):
        for _ in range(2):
            tests.append(fmt([rng.randint(1, n - i) for i in range(n)], [rng.randint(1, 9) for _ in range(n)]))
    tests.append(fmt([1] * 20, [rng.randint(1, B) for _ in range(20)]))
    tests.append(fmt([20 - i for i in range(20)], [rng.randint(1, B) for _ in range(20)]))
    def big(n, mode):
        if mode == 'rand':
            ds = [rng.randint(1, n - i) for i in range(n)]
        elif mode == 'front':
            ds = [1] * n
        elif mode == 'back':
            ds = [n - i for i in range(n)]
        else:
            ds = [(n - i + 1) // 2 for i in range(n)]
        return fmt(ds, [rng.randint(1, B) for _ in range(n)])
    tests.append(big(2000, 'rand'))
    N = 100000
    for mode in ('rand', 'front', 'mid'):
        tests.append(big(N, mode))
    return tests
